265		// binaries exactly where the existing one lives, regardless of the user's
266		// GOBIN/GOPATH config. Otherwise `go install` would land them in $GOBIN,
267		// which may not be the directory their PATH resolves `entire` from.
268		stagingDir, err := os.MkdirTemp("", "entire-upgrade-go-*")
269		if err != nil {
270			return fmt.Errorf("create staging dir: %w", err)
271		}
272		defer os.RemoveAll(stagingDir)
273	
274		// git-remote-entire ships alongside entire, so install it into the same
275		// directory the entire binary already lives in.
276		binDir := filepath.Dir(install.BinaryPath)
277	
278		for _, pkg := range goInstallPackages {
279			module := pkg + "@" + target.Tag()
280			if err := runner.RunEnv(ctx, []string{"GOBIN=" + stagingDir}, "go", "install", module); err != nil {
281				return fmt.Errorf("go install %s: %w", module, err)
282			}
283	
284			binaryName := executableName(filepath.Base(pkg))
285			stagedBinary := filepath.Join(stagingDir, binaryName)
286			if _, err := os.Stat(stagedBinary); err != nil {
287				return fmt.Errorf("go install %s completed but produced no binary at %s: %w", module, stagedBinary, err)
288			}
289	
290			dst := filepath.Join(binDir, binaryName)
291			if err := replaceBinary(stagedBinary, dst); err != nil {
292				return fmt.Errorf("replace %s: %w", dst, err)
293			}
294		}
295		return nil
296	}
