298	// replaceBinary atomically replaces dst with the contents of src. The new
299	// file is staged as a sibling of dst so the rename stays on one filesystem.
300	func replaceBinary(src, dst string) error {
301		dir := filepath.Dir(dst)
302		tmp, err := os.CreateTemp(dir, ".entire-upgrade-*")
303		if err != nil {
304			return fmt.Errorf("create temp file in %s: %w", dir, err)
305		}
306		tmpPath := tmp.Name()
307		cleanup := func() { _ = os.Remove(tmpPath) }
308	
309		srcFile, err := os.Open(src)
310		if err != nil {
311			_ = tmp.Close()
312			cleanup()
313			return err
314		}
315		defer srcFile.Close()
316	
317		if _, err := io.Copy(tmp, srcFile); err != nil {
318			_ = tmp.Close()
319			cleanup()
320			return err
321		}
322		if err := tmp.Chmod(0o755); err != nil {
323			_ = tmp.Close()
324			cleanup()
325			return err
326		}
327		if err := tmp.Close(); err != nil {
328			cleanup()
329			return err
330		}
331		if err := os.Rename(tmpPath, dst); err != nil {
332			cleanup()
333			return err
334		}
335		return nil
336	}
