345	func ParseChannel(s string) (Channel, error) {
346		switch Channel(strings.ToLower(strings.TrimSpace(s))) {
347		case StableChannel:
348			return StableChannel, nil
349		case NightlyChannel:
350			return NightlyChannel, nil
351		default:
352			return "", fmt.Errorf("unsupported channel %q", s)
353		}
354	}
