package versioninfo

import (
	"runtime/debug"
	"testing"
)

func buildInfo(mainVersion string, settings ...debug.BuildSetting) *debug.BuildInfo {
	return &debug.BuildInfo{
		Main:     debug.Module{Path: "github.com/entireio/cli", Version: mainVersion},
		Settings: settings,
	}
}

func TestResolve(t *testing.T) {
	tests := []struct {
		name        string
		version     string
		commit      string
		info        *debug.BuildInfo
		ok          bool
		wantVersion string
		wantCommit  string
	}{
		{
			name:        "ldflags stamp wins over build info",
			version:     "0.6.2",
			commit:      "abc1234",
			info:        buildInfo("v9.9.9"),
			ok:          true,
			wantVersion: "0.6.2",
			wantCommit:  "abc1234",
		},
		{
			name:        "module install recovers tagged version",
			version:     "dev",
			commit:      "unknown",
			info:        buildInfo("v0.6.2-nightly.202605160654.ddf1a331"),
			ok:          true,
			wantVersion: "0.6.2-nightly.202605160654.ddf1a331",
			wantCommit:  "unknown",
		},
		{
			name:    "local build recovers commit from vcs revision",
			version: "dev",
			commit:  "unknown",
			info: buildInfo("(devel)",
				debug.BuildSetting{Key: "vcs.revision", Value: "ddf1a331c0ffee1234567890abcdef0987654321"},
				debug.BuildSetting{Key: "vcs.modified", Value: "true"},
			),
			ok:          true,
			wantVersion: "dev",
			wantCommit:  "ddf1a331c0ffee1234567890abcdef0987654321",
		},
		{
			name:    "explicit commit survives build-info fallback",
			version: "dev",
			commit:  "abc1234",
			info: buildInfo("(devel)",
				debug.BuildSetting{Key: "vcs.revision", Value: "ddf1a331c0ffee1234567890abcdef0987654321"},
			),
			ok:          true,
			wantVersion: "dev",
			wantCommit:  "abc1234",
		},
		{
			name:        "missing build info leaves defaults",
			version:     "dev",
			commit:      "unknown",
			info:        nil,
			ok:          false,
			wantVersion: "dev",
			wantCommit:  "unknown",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			gotVersion, gotCommit := resolve(tt.version, tt.commit, tt.info, tt.ok)
			if gotVersion != tt.wantVersion {
				t.Errorf("version = %q, want %q", gotVersion, tt.wantVersion)
			}
			if gotCommit != tt.wantCommit {
				t.Errorf("commit = %q, want %q", gotCommit, tt.wantCommit)
			}
		})
	}
}
package versioninfo

import (
	"runtime/debug"
	"strings"
)

var (
	Version = "dev"
	Commit  = "unknown"
)

func Load() {
	info, ok := debug.ReadBuildInfo()
	Version, Commit = resolve(Version, Commit, info, ok)
}

func resolve(version, commit string, info *debug.BuildInfo, ok bool) (string, string) {
	if version != "dev" || !ok || info == nil {
		return version, commit
	}

	if v := info.Main.Version; v != "" && v != "(devel)" {
		version = strings.TrimPrefix(v, "v") // match GoReleaser's {{.Version}}
	}
	// Only fill an unset commit; an explicit ldflags stamp always wins.
	if commit == "unknown" {
		for _, setting := range info.Settings {
			if setting.Key == "vcs.revision" && setting.Value != "" {
				commit = setting.Value
			}
		}
	}

	return version, commit
}
