394	func runFakeCommand() int {
395		name := strings.TrimSuffix(filepath.Base(os.Args[0]), ".exe")
396		args := os.Args[1:]
397		stateDir := os.Getenv("ENTIRE_UPGRADE_FAKE_STATE_DIR")
398		if stateDir == "" {
399			fmt.Fprintln(os.Stderr, "missing ENTIRE_UPGRADE_FAKE_STATE_DIR")
400			return 2
401		}
402	
403		switch name {
404		case "entire":
405			return fakeEntire(stateDir)
406		case "brew":
407			return fakeBrew(stateDir, args)
408		case "go":
409			return fakeGo(stateDir, args)
410		case "bash":
411			return fakeBash(stateDir, args)
412		default:
413			fmt.Fprintf(os.Stderr, "unknown fake command %q\n", name)
414			return 2
415		}
416	}
