428	func fakeBrew(stateDir string, args []string) int {
429		if len(args) == 1 && args[0] == "--prefix" {
430			fmt.Println(os.Getenv("ENTIRE_UPGRADE_FAKE_BREW_PREFIX"))
431			return 0
432		}
433	
434		if err := appendFakeLog(stateDir, "brew", args); err != nil {
435			fmt.Fprintln(os.Stderr, err)
436			return 1
437		}
438		if len(args) >= 3 && (args[0] == "install" || args[0] == "upgrade") && args[1] == "--cask" {
439			if err := fakeSetVersionForCask(stateDir, args[2]); err != nil {
440				fmt.Fprintln(os.Stderr, err)
441				return 1
442			}
443		}
444		return 0
445	}
