447	func fakeGo(stateDir string, args []string) int {
448		if len(args) == 2 && args[0] == "env" {
449			switch args[1] {
450			case "GOBIN":
451				fmt.Println(os.Getenv("ENTIRE_UPGRADE_FAKE_GOBIN"))
452			case "GOPATH":
453				fmt.Println(os.Getenv("ENTIRE_UPGRADE_FAKE_GOPATH"))
454			}
455			return 0
456		}
457	
458		if err := appendFakeLog(stateDir, "go", args); err != nil {
459			fmt.Fprintln(os.Stderr, err)
460			return 1
461		}
462		if len(args) == 2 && args[0] == "install" {
463			spec := args[1]
464			at := strings.LastIndex(spec, "@")
465			version := strings.TrimPrefix(spec[at+1:], "v")
466			binName := commandFilename(filepath.Base(spec[:at]))
467			// The entire binary backs `entire --version`, used for verification.
468			// git-remote-entire shares the same release version, so writing it
469			// for either package keeps version.txt correct.
470			if err := os.WriteFile(filepath.Join(stateDir, "version.txt"), []byte(version), 0o644); err != nil {
471				fmt.Fprintln(os.Stderr, err)
472				return 1
473			}
474			// Mirror real `go install`: write the produced binary into $GOBIN.
475			// The production code routes this through a staging directory and
476			// renames the result over the existing binary.
477			if goBin := os.Getenv("GOBIN"); goBin != "" {
478				if err := os.MkdirAll(goBin, 0o755); err != nil {
479					fmt.Fprintln(os.Stderr, err)
480					return 1
481				}
482				executable, err := os.Executable()
483				if err != nil {
484					fmt.Fprintln(os.Stderr, err)
485					return 1
486				}
487				if err := copyFakeCommand(executable, filepath.Join(goBin, binName)); err != nil {
488					fmt.Fprintln(os.Stderr, err)
489					return 1
490				}
491			}
492		}
493		return 0
494	}
