496	func fakeBash(stateDir string, args []string) int {
497		if err := appendFakeLog(stateDir, "bash", args); err != nil {
498			fmt.Fprintln(os.Stderr, err)
499			return 1
500		}
501	
502		channel := StableChannel
503		if strings.Contains(strings.Join(args, " "), "--channel nightly") {
504			channel = NightlyChannel
505		}
506		if err := fakeSetVersionForChannel(stateDir, channel); err != nil {
507			fmt.Fprintln(os.Stderr, err)
508			return 1
509		}
510		return 0
511	}
512	
513	func fakeSetVersionForCask(stateDir, cask string) error {
514		channel := StableChannel
515		if cask == "entire@nightly" {
516			channel = NightlyChannel
517		}
518		if err := fakeSetVersionForChannel(stateDir, channel); err != nil {
519			return err
520		}
521		return fakeInstallBrewCask(cask, fakeVersionForChannel(channel))
522	}
523	
524	func fakeSetVersionForChannel(stateDir string, channel Channel) error {
525		return os.WriteFile(filepath.Join(stateDir, "version.txt"), []byte(fakeVersionForChannel(channel)), 0o644)
526	}
527	
528	func fakeVersionForChannel(channel Channel) string {
529		if channel == NightlyChannel {
530			return os.Getenv("ENTIRE_UPGRADE_FAKE_NIGHTLY_VERSION")
531		}
532		return os.Getenv("ENTIRE_UPGRADE_FAKE_STABLE_VERSION")
533	}
534	
535	func fakeInstallBrewCask(cask, version string) error {
536		prefix := os.Getenv("ENTIRE_UPGRADE_FAKE_BREW_PREFIX")
537		if prefix == "" {
538			return nil
539		}
540	
541		executable, err := os.Executable()
542		if err != nil {
543			return err
544		}
545	
546		caskBin := filepath.Join(prefix, "Caskroom", cask, version, commandFilename("entire"))
547		if err := copyFakeCommand(executable, caskBin); err != nil {
548			return err
549		}
550	
551		pathBin := filepath.Join(prefix, "bin", commandFilename("entire"))
552		if err := os.MkdirAll(filepath.Dir(pathBin), 0o755); err != nil {
553			return err
554		}
555		if err := os.Remove(pathBin); err != nil && !os.IsNotExist(err) {
556			return err
557		}
558		return os.Symlink(caskBin, pathBin)
559	}
560	
561	func copyFakeCommand(srcPath, dstPath string) error {
562		if err := os.MkdirAll(filepath.Dir(dstPath), 0o755); err != nil {
563			return err
564		}
565	
566		src, err := os.Open(srcPath)
567		if err != nil {
568			return err
569		}
570		defer src.Close()
571	
572		dst, err := os.OpenFile(dstPath, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o755)
573		if err != nil {
574			return err
575		}
576		if _, err := io.Copy(dst, src); err != nil {
577			_ = dst.Close()
578			return err
579		}
580		return dst.Close()
581	}
582	
583	func appendFakeLog(stateDir, name string, args []string) error {
584		line := strings.Join(append([]string{name}, args...), " ") + "\n"
585		path := filepath.Join(stateDir, "commands.log")
586		f, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
587		if err != nil {
588			return err
589		}
590		defer f.Close()
591		_, err = f.WriteString(line)
592		return err
593	}
594	
595	func commandFilename(name string) string {
596		if runtime.GOOS == "windows" {
597			return name + ".exe"
598		}
599		return name
600	}
