			install: Installation{Method: MethodHomebrew, BrewCask: "entire"},
			channel: NightlyChannel,
			want: []string{
				"brew tap entireio/tap",
				"brew update",
				"brew uninstall --cask entire",
				"brew install --cask entire@nightly",
			},
		},
