			install: Installation{Method: MethodHomebrew, BrewCask: "entire@nightly"},
			channel: StableChannel,
			want: []string{
				"brew tap entireio/tap",
				"brew update",
				"brew uninstall --cask entire@nightly",
				"brew install --cask entire",
			},
		},
