			name:    "curl uses selected channel",
			install: Installation{Method: MethodCurl},
			channel: NightlyChannel,
			want: []string{
				"bash -c set -o pipefail; curl -fsSL https://entire.io/install.sh | bash -s -- --channel nightly",
