	if brewPrefix != "" {
		candidates = append(candidates,
			candidate{dir: filepath.Join(brewPrefix, "Caskroom", "entire@nightly"), cask: "entire@nightly"},
			candidate{dir: filepath.Join(brewPrefix, "Caskroom", "entire"), cask: "entire"},
