91	// resolveVersion turns a binary's `--version` output into a Version, falling
92	// back to the Go build info compiled into the binary when the output can't be
93	// parsed (the go-install build whose --version prints "dev"). entire and
94	// git-remote-entire share this so both report their version identically.
95	func resolveVersion(versionOut []byte, resolvedPath string) (Version, error) {
96		version, err := ParseVersion(string(versionOut))
97		if err == nil {
98			return version, nil
99		}
100		buildVersion, buildErr := versionFromGoBuildInfo(resolvedPath)
101		if buildErr != nil {
102			return Version{}, fmt.Errorf("%w; Go build info fallback failed: %v", err, buildErr)
103		}
104		return buildVersion, nil
