108	// entire — `--version`, then build info — but degrades to an absent Version
109	// instead of erroring, since the helper may be missing or predate the
110	// --version flag (older releases print a usage banner and exit non-zero). An
111	// absent Version signals callers to (re)install it.
112	func detectHelperVersion(ctx context.Context, helperPath string) Version {
113		resolved, err := filepath.EvalSymlinks(helperPath)
