46	func (r ExecRunner) RunEnv(ctx context.Context, env []string, name string, args ...string) error {
47		cmd := exec.CommandContext(ctx, name, args...)
48		cmd.Stdout = r.Stdout
49		cmd.Stderr = r.Stderr
50		cmd.Stdin = os.Stdin
51		cmd.Env = append(commandEnvWithoutGitHubToken(os.Environ()), env...)
52		return cmd.Run()
53	}
54	
55	func commandEnvWithoutGitHubToken(env []string) []string {
56		filtered := env[:0]
57		for _, entry := range env {
58			if strings.HasPrefix(entry, "GITHUB_TOKEN=") {
59				continue
60			}
61			filtered = append(filtered, entry)
62		}
63		return filtered
64	}
65	
66	func Run(ctx context.Context, opts Options) error {
67		channel := opts.Channel
68		if channel == "" {
69			channel = StableChannel
70		}
71		stdout := opts.Stdout
72		if stdout == nil {
73			stdout = os.Stdout
74		}
75		stderr := opts.Stderr
76		if stderr == nil {
77			stderr = os.Stderr
78		}
79		stdin := opts.Stdin
80		if stdin == nil {
81			stdin = os.Stdin
82		}
83	
84		install, err := DetectInstallation(ctx)
85		if err != nil {
86			return err
87		}
88		fmt.Fprintf(stdout, "Detected Entire CLI %s at %s (%s install)\n", install.Version, install.BinaryPath, install.Method)
89	
90		latest, err := (ReleaseChecker{}).Latest(ctx, channel)
91		if err != nil {
92			return err
93		}
94		fmt.Fprintf(stdout, "Latest %s build is %s\n", channel, latest)
95	
96		compare := latest.Compare(install.Version)
97		channelSwitch := opts.ExplicitChannel && !installationMatchesChannel(install, channel)
98		if compare <= 0 && !channelSwitch {
99			fmt.Fprintf(stdout, "Entire CLI is already up to date for the %s channel.\n", channel)
100			return nil
101		}
102	
103		action := "Upgrade"
104		if compare < 0 || channelSwitch {
105			action = "Switch"
106		}
107	
108		if !opts.Yes {
109			prompt := fmt.Sprintf("%s Entire CLI from %s to %s using the %s installer? [Y/n] ", action, install.Version, latest, install.Method)
110			ok, err := confirm(stdout, stdin, prompt)
111			if err != nil {
112				return err
113			}
114			if !ok {
115				fmt.Fprintln(stdout, "Aborted.")
116				return ErrAborted
117			}
118		}
119	
120		if err := Install(ctx, ExecRunner{Stdout: stdout, Stderr: stderr}, install, latest, channel); err != nil {
121			return err
122		}
123	
124		verified, err := DetectInstallation(ctx)
125		if err != nil {
126			return fmt.Errorf("upgrade command completed, but verification failed: %w", err)
127		}
128		if verified.Version.Compare(latest) < 0 {
129			return fmt.Errorf("upgrade command completed, but Entire CLI still reports %s; expected at least %s", verified.Version, latest)
130		}
131		if !installationMatchesChannel(verified, channel) {
132			return fmt.Errorf("upgrade command completed, but Entire CLI is still on the %s channel; expected %s", installedChannel(verified), channel)
133		}
134	
135		fmt.Fprintf(stdout, "Entire CLI upgrade complete: entire %s installed to %s (via %s).\n", verified.Version, verified.BinaryPath, verified.Method)
136		return nil
137	}
