139	// confirm reads a yes/no answer from r, defaulting to yes on an empty line.
140	// EOF is treated as a decline so non-interactive callers without --yes do not
141	// silently proceed.
142	func confirm(w io.Writer, r io.Reader, prompt string) (bool, error) {
143		fmt.Fprint(w, prompt)
144		scanner := bufio.NewScanner(r)
145		if !scanner.Scan() {
146			if err := scanner.Err(); err != nil {
147				return false, fmt.Errorf("read confirmation: %w", err)
148			}
149			fmt.Fprintln(w)
150			return false, nil
151		}
152		answer := strings.ToLower(strings.TrimSpace(scanner.Text()))
153		switch answer {
154		case "", "y", "yes":
155			return true, nil
156		default:
157			return false, nil
158		}
159	}
