197	func goBinDirs(env Environment) []string {
198		var dirs []string
199		seen := map[string]struct{}{}
200		addDir := func(dir string) {
201			dir = filepath.Clean(dir)
202			if _, ok := seen[dir]; ok {
203				return
204			}
205			seen[dir] = struct{}{}
206			dirs = append(dirs, dir)
207		}
208		if env.GoBin != "" {
209			addDir(env.GoBin)
210		}
211		if env.GoPath == "" && env.Home != "" {
212			addDir(filepath.Join(env.Home, "go", "bin"))
213		}
214		for _, p := range filepath.SplitList(env.GoPath) {
215			if p == "" {
216				continue
217			}
218			addDir(filepath.Join(p, "bin"))
219		}
220		return dirs
221	}
