231	func isSubpath(path, dir string) bool {
232		path = filepath.Clean(path)
233		dir = filepath.Clean(dir)
234		rel, err := filepath.Rel(dir, path)
235		if err != nil {
236			return false
237		}
238		return rel == "." || (rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)))
239	}
