96		// Resolve every release binary beside the anchor. The anchor is the one we
97		// found on PATH, so its version must be readable; the rest may legitimately
98		// be missing or predate --version, in which case an absent Version tells
99		// callers to (re)install them.
100		binDir := filepath.Dir(binaryPath)
101		for _, rb := range releaseBinaries {
102			bin := ManagedBinary{Name: rb.Name, GoPkg: rb.GoPkg, Path: filepath.Join(binDir, executableName(rb.Name))}
103			version, verr := binaryVersion(ctx, bin.Path)
104			if verr != nil {
105				if rb.Name == anchorBinary {
106					return Installation{}, verr
107				}
108				version = Version{}
109			}
110			bin.Version = version
